 BungeeMatch m;string folder;int errors;readonly StringBuilder report=new StringBuilder();void Check(bool ok,string label){report.AppendLine((ok?"PASS ":"FAIL ")+label);File.WriteAllText(folder+"/progress.txt",report.ToString());if(!ok)errors++;}void Error(string s,string stack,LogType type){if(type==LogType.Error||type==LogType.Exception){errors++;report.AppendLine("ERROR "+s);}}
 IEnumerator Fresh(int count){m.enabled=true;m.SetupScreen();m.setup.count=count;m.NormalizeSetup();m.AllBots();Check(m.StartMatch(),"physical slice starts count="+count);float until=Time.realtimeSinceStartup+8;while(m.Phase!=BungeePhase.Demolition&&Time.realtimeSinceStartup<until)yield return null;Check(m.Phase==BungeePhase.Demolition,"countdown releases physical trucks");m.enabled=false;}
