 yield return Fresh(1);b=m.bays[0];var first=Array.Find(b.modules,x=>x.level==2&&x.name.EndsWith("/ 0"));var second=Array.Find(b.modules,x=>x.level==2&&x.name.EndsWith("/ 1"));Check(first!=null&&second!=null,"representative ten-storey vendor support graph exists");yield return Impact(b,first);Check(Array.Exists(b.modules,x=>x.level==2&&x.name.StartsWith("Floor")&&x.gameObject.activeSelf),"one lost column leaves adequate aggregate support");yield return Impact(b,second);yield return new WaitForSeconds(1);int upper=0;foreach(var module in b.modules)if(module.level>2&&module.core.HasCollapsed)upper++;Check(upper==35,"Core-Collapse support loss propagates through all unsupported upper modules count="+upper);Check(b.Score>0&&b.Collapses>2&&b.debris.Count>2,"player-caused secondary collapse receives bounded module scores");int scored=b.Score;b.Award(first);Check(b.Score==scored,"duplicate collapse notification cannot farm points");bool falling=false;foreach(var d in b.debris)foreach(var body in d.GetComponentsInChildren<Rigidbody>())falling|=body.linearVelocity.y< -1;Check(falling,"actual fractured architecture falls under PhysX");
 m.enabled=true;typeof(BungeeMatch).GetProperty("Clock").SetValue(m,0f);yield return new WaitForFixedUpdate();m.enabled=false;Check(m.Phase==BungeePhase.Finale,"timer locks scores before support-release finale");scored=b.Score;for(int level=0;level<10;level++)b.FinaleStep(level);yield return new WaitForSeconds(1);Check(b.Score==scored&&Array.TrueForAll(b.modules,x=>x.core.HasCollapsed),"complete foundation-to-roof finale adds no score");yield return Fresh(4);for(int i=0;i<4;i++){b=m.bays[i];Check(b.Score==0&&b.modules.Length==50&&b.debris.Count==0,"four-bay tower/cable reset slot="+i);b.spring.spring=b.springStrength;b.spring.damper=b.damping;}float[] minimum={1000,1000,1000,1000};until=Time.realtimeSinceStartup+6;while(Time.realtimeSinceStartup<until){for(int i=0;i<4;i++)minimum[i]=Mathf.Min(minimum[i],m.bays[i].truck.body.position.y);yield return null;}for(int i=0;i<4;i++)Check(minimum[i]<30&&Vector3.Distance(m.bays[i].truck.body.position,m.bays[i].craneAnchor.position)<75,"four simultaneous independent suspended trucks slot="+i+" minY="+minimum[i]);Check(FindObjectsByType<AudioListener>(FindObjectsInactive.Exclude).Length==1,"one listener");report.AppendLine("ERRORS="+errors+". Core-Collapse native physics/support slice; Rope Toolkit absent, explicit SpringJoint/LineRenderer fallback only. No hardware/human test or GPU benchmark.");File.WriteAllText(folder+"/result.txt",report.ToString());Debug.Log("BUNGEE_SLICE_COMPLETE "+report);Application.logMessageReceived-=Error;m.enabled=true;m.SetupScreen();Time.timeScale=1;if(!Application.isEditor)Application.Quit(errors==0?0:2);}
